"use client";
/**
 * Exam preparation: the official syllabus of an exam (every subtopic links to the page of the official
 * notice it was read from), the previous year question papers on the official site, and the user's own
 * study plans with a week-by-week list whose items can be marked done.
 *
 * Nothing is cached or computed beyond presentation: the plan itself is generated by the backend
 * (deterministic, see backend/services/study_plan.py) and every status change is a PATCH whose
 * response replaces the item on screen.
 */
import { useCallback, useEffect, useMemo, useState, type FormEvent } from "react";

import { ErrorNote, Shell, errText, fmtDate, useSession } from "@/components/ui";
import { api, ApiError } from "@/lib/api";
import {
  PLAN_ITEM_STATUSES,
  type PlanIn,
  type PlanItem,
  type PlanItemStatus,
  type QuestionPaper,
  type StudyPlan,
  type Syllabus,
} from "@/lib/types-prep";

/** Codes the UPSC previous-question-paper source assigns (backend/sources/upsc_pyq.py); any code can be typed. */
const KNOWN_CODES = [
  "CSE", "IFS", "CDS", "NDA", "ESE", "CMS", "CAPF", "IES_ISS", "GEOSCIENTIST", "CISF_AC_LDCE", "CBI_DSP_LDCE", "SO_LDCE",
];

export default function PrepPage() {
  const user = useSession();
  return <Shell user={user}>{user && <PrepView />}</Shell>;
}

/** PDF viewers open at a page with the #page=N fragment. */
function pageLink(url: string, page: number | null): string {
  return page ? `${url}#page=${page}` : url;
}

/** "YYYY-MM-DD" as a local date (new Date("YYYY-MM-DD") would be UTC midnight). */
function parseDay(s: string): Date {
  const [y, m, d] = s.split("-").map(Number);
  return new Date(y, m - 1, d);
}

function isoDay(d: Date): string {
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

function addDays(d: Date, n: number): Date {
  const r = new Date(d);
  r.setDate(r.getDate() + n);
  return r;
}

function shortDay(d: Date): string {
  return d.toLocaleDateString("en-IN", { day: "2-digit", month: "short" });
}

function hours(h: number): string {
  return `${Math.round(h * 10) / 10} h`;
}

const LINK = "text-blue-700 underline";
const CARD = "rounded border border-slate-200 bg-white p-4";

function PrepView() {
  const [codeInput, setCodeInput] = useState("");
  const [code, setCode] = useState<string | null>(null);

  const [syllabus, setSyllabus] = useState<Syllabus | null>(null);
  const [syllabusError, setSyllabusError] = useState<string | null>(null);
  const [papers, setPapers] = useState<QuestionPaper[] | null>(null);
  const [papersError, setPapersError] = useState<string | null>(null);

  const [plans, setPlans] = useState<StudyPlan[] | null>(null);
  const [plansError, setPlansError] = useState<string | null>(null);
  const [planId, setPlanId] = useState<string | null>(null);

  // The user's plans first: an existing plan decides which exam to open.
  useEffect(() => {
    let live = true;
    api<StudyPlan[]>("/prep/plans")
      .then((ps) => {
        if (!live) return;
        setPlans(ps);
        if (ps.length) {
          setPlanId(ps[0].id);
          setCode(ps[0].exam_code);
          setCodeInput(ps[0].exam_code);
        }
      })
      .catch((e) => live && setPlansError(errText(e)));
    return () => {
      live = false;
    };
  }, []);

  useEffect(() => {
    if (!code) return;
    let live = true;
    setSyllabus(null);
    setSyllabusError(null);
    setPapers(null);
    setPapersError(null);
    const c = encodeURIComponent(code);
    api<Syllabus>(`/prep/exams/${c}/syllabus`)
      .then((s) => live && setSyllabus(s))
      .catch((e) => live && setSyllabusError(errText(e)));
    api<QuestionPaper[]>(`/prep/exams/${c}/papers`)
      .then((p) => live && setPapers(p))
      .catch((e) => live && setPapersError(errText(e)));
    return () => {
      live = false;
    };
  }, [code]);

  function openCode(e: FormEvent) {
    e.preventDefault();
    const c = codeInput.trim().toUpperCase();
    if (!c) return;
    setCode(c);
    // The plan on screen always belongs to the open exam, so its page and paper links can resolve.
    if (plan?.exam_code !== c) setPlanId(plans?.find((p) => p.exam_code === c)?.id ?? null);
  }

  function selectPlan(id: string) {
    setPlanId(id);
    const p = plans?.find((x) => x.id === id);
    if (p && p.exam_code !== code) {
      setCode(p.exam_code);
      setCodeInput(p.exam_code);
    }
  }

  const onCreated = useCallback((p: StudyPlan) => {
    setPlans((ps) => [p, ...(ps ?? [])]);
    setPlanId(p.id);
  }, []);

  const onItem = useCallback((planId: string, item: PlanItem) => {
    setPlans((ps) =>
      (ps ?? []).map((p) => (p.id === planId ? { ...p, items: p.items.map((i) => (i.id === item.id ? item : i)) } : p)),
    );
  }, []);

  const plan = plans?.find((p) => p.id === planId) ?? null;
  const codeOptions = useMemo(
    () => Array.from(new Set([...(plans ?? []).map((p) => p.exam_code), ...KNOWN_CODES])),
    [plans],
  );

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-xl font-semibold">Study plan</h1>
        <p className="text-sm text-slate-500">
          Official syllabus and previous year papers for an exam, and a week-by-week plan built from them.
        </p>
      </div>

      <form onSubmit={openCode} className="flex flex-wrap items-end gap-2">
        <label className="text-sm">
          <span className="mb-1 block text-slate-600">Exam code</span>
          <input
            list="prep-exam-codes"
            value={codeInput}
            onChange={(e) => setCodeInput(e.target.value)}
            placeholder="e.g. CSE"
            className="w-48 rounded border border-slate-300 px-2 py-1 font-mono uppercase"
          />
          <datalist id="prep-exam-codes">
            {codeOptions.map((c) => (
              <option key={c} value={c} />
            ))}
          </datalist>
        </label>
        <button type="submit" className="rounded bg-blue-700 px-3 py-1.5 text-sm text-white hover:bg-blue-800">
          Open
        </button>
      </form>

      <section>
        <h2 className="mb-2 font-medium">Your study plans</h2>
        <ErrorNote error={plansError} />
        {!plans && !plansError && <p className="text-sm text-slate-500">Loading…</p>}
        {plans && !plans.length && <p className="text-sm text-slate-500">No study plans yet. Open an exam with a syllabus and create one below.</p>}
        {plans && plans.length > 0 && (
          <div className="flex flex-wrap gap-2">
            {plans.map((p) => {
              const done = p.items.filter((i) => i.status === "DONE").length;
              return (
                <button
                  key={p.id}
                  onClick={() => selectPlan(p.id)}
                  className={`rounded border px-3 py-1.5 text-left text-sm ${
                    p.id === planId ? "border-blue-600 bg-blue-50" : "border-slate-200 bg-white hover:border-slate-400"
                  }`}
                >
                  <span className="font-mono font-medium">{p.exam_code}</span> · exam {fmtDate(p.target_date)}
                  <span className="block text-xs text-slate-500">
                    {hours(p.weekly_hours)}/week · {done}/{p.items.length} done
                  </span>
                </button>
              );
            })}
          </div>
        )}
      </section>

      {plan && <PlanView plan={plan} syllabus={syllabus} papers={papers} onItem={onItem} />}

      {!code && <p className="text-sm text-slate-500">Pick an exam code to see its syllabus and question papers.</p>}

      {code && (
        <>
          <section>
            <h2 className="mb-2 font-medium">
              Create a study plan for <span className="font-mono">{code}</span>
            </h2>
            {syllabus ? (
              <PlanForm code={code} syllabus={syllabus} onCreated={onCreated} />
            ) : (
              <p className="text-sm text-slate-500">
                {syllabusError ? "A plan needs an official syllabus for this exam." : "Loading syllabus…"}
              </p>
            )}
          </section>

          <section>
            <h2 className="mb-2 font-medium">
              Official syllabus · <span className="font-mono">{code}</span>
            </h2>
            <ErrorNote error={syllabusError} />
            {!syllabus && !syllabusError && <p className="text-sm text-slate-500">Loading…</p>}
            {syllabus && <SyllabusView s={syllabus} />}
          </section>

          <section>
            <h2 className="mb-2 font-medium">
              Previous year question papers · <span className="font-mono">{code}</span>
            </h2>
            <ErrorNote error={papersError} />
            {!papers && !papersError && <p className="text-sm text-slate-500">Loading…</p>}
            {papers && <PapersView papers={papers} />}
          </section>
        </>
      )}
    </div>
  );
}

function SyllabusView({ s }: { s: Syllabus }) {
  if (!s.sections.length) return <p className="text-sm text-slate-500">The stored syllabus has no topics.</p>;
  const url = s.notice_url;
  return (
    <div className="space-y-3">
      <p className="text-sm text-slate-500">
        {url ? (
          <a className={LINK} href={url} target="_blank" rel="noreferrer">
            Official syllabus document
          </a>
        ) : (
          "Official document URL not recorded"
        )}{" "}
        · retrieved {fmtDate(s.retrieved_at, true)} · parser {s.parser_version}
      </p>
      {s.sections.map((sec, si) => (
        <details key={`${sec.name}-${si}`} className={CARD} open={s.sections.length === 1}>
          <summary className="cursor-pointer font-medium">
            {sec.name} <span className="text-sm font-normal text-slate-500">({sec.topics.length} topics)</span>
          </summary>
          {sec.note && <p className="mt-2 text-sm italic text-slate-600">{sec.note}</p>}
          <ol className="mt-3 space-y-3">
            {sec.topics.map((t) => {
              const pages = Array.from(new Set(t.subtopics.map((x) => x.page))).sort((a, b) => a - b);
              return (
                <li key={`${t.order}-${t.title}`} className="border-t border-slate-100 pt-2 text-sm">
                  <div className="flex flex-wrap items-baseline gap-2">
                    <span className="font-medium">{t.title}</span>
                    {t.part && <span className="text-xs text-slate-500">{t.part}</span>}
                    <span className="ml-auto text-xs">
                      {pages.map((p, i) => (
                        <span key={p}>
                          {i > 0 && ", "}
                          <PageRef url={url} page={p} />
                        </span>
                      ))}
                    </span>
                  </div>
                  {t.subtopics.length > 0 && (
                    <ul className="mt-1 list-disc space-y-0.5 pl-5 text-slate-700">
                      {t.subtopics.map((st, i) => (
                        <li key={i}>
                          {st.text} <PageRef url={url} page={st.page} small />
                        </li>
                      ))}
                    </ul>
                  )}
                </li>
              );
            })}
          </ol>
        </details>
      ))}
    </div>
  );
}

function PageRef({ url, page, small }: { url: string | null; page: number; small?: boolean }) {
  const cls = small ? "text-xs text-blue-700 underline" : LINK;
  if (!url) return <span className="text-xs text-slate-500">page {page}</span>;
  return (
    <a className={cls} href={pageLink(url, page)} target="_blank" rel="noreferrer">
      page {page}
    </a>
  );
}

function PapersView({ papers }: { papers: QuestionPaper[] }) {
  const years = useMemo(() => Array.from(new Set(papers.map((p) => p.year))).sort((a, b) => b - a), [papers]);
  const [year, setYear] = useState<string>("");
  if (!papers.length) return <p className="text-sm text-slate-500">No question papers recorded for this exam.</p>;
  const shown = year ? papers.filter((p) => String(p.year) === year) : papers;
  return (
    <div className="space-y-2">
      <label className="text-sm text-slate-600">
        Year{" "}
        <select value={year} onChange={(e) => setYear(e.target.value)} className="rounded border border-slate-300 px-2 py-1">
          <option value="">All ({papers.length})</option>
          {years.map((y) => (
            <option key={y} value={y}>
              {y}
            </option>
          ))}
        </select>
      </label>
      <div className="overflow-x-auto rounded border border-slate-200 bg-white">
        <table className="w-full text-sm">
          <thead className="bg-slate-100 text-left">
            <tr>
              <th className="px-3 py-2">Year</th>
              <th className="px-3 py-2">Examination</th>
              <th className="px-3 py-2">Paper</th>
              <th className="px-3 py-2">Official document</th>
            </tr>
          </thead>
          <tbody>
            {shown.map((p) => (
              <tr key={p.id} className="border-t border-slate-100 align-top">
                <td className="px-3 py-2">{p.year}</td>
                <td className="px-3 py-2">
                  {p.exam_name}
                  {p.stage && <span className="block text-xs text-slate-500">{p.stage}</span>}
                </td>
                <td className="px-3 py-2">
                  {p.paper_name}
                  {p.category && <span className="block text-xs text-slate-500">{p.category}</span>}
                </td>
                <td className="whitespace-nowrap px-3 py-2">
                  <a className={LINK} href={p.official_url} target="_blank" rel="noreferrer">
                    PDF{p.size_label ? ` (${p.size_label})` : ""}
                  </a>
                  {p.raw_document_id && <span className="block text-xs text-slate-500">stored copy · used in plans</span>}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function PlanForm({ code, syllabus, onCreated }: { code: string; syllabus: Syllabus; onCreated: (p: StudyPlan) => void }) {
  const today = isoDay(new Date());
  const [examDate, setExamDate] = useState("");
  const [weeklyHours, setWeeklyHours] = useState("15");
  const [startDate, setStartDate] = useState("");
  const [sections, setSections] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const names = syllabus.sections.map((s) => s.name);

  useEffect(() => {
    setSections([]);
    setError(null);
  }, [code]);

  async function submit(e: FormEvent) {
    e.preventDefault();
    const h = Number(weeklyHours);
    if (!examDate) return setError("Pick the exam date.");
    if (!(h > 0 && h <= 112)) return setError("Weekly hours must be more than 0 and at most 112.");
    const body: PlanIn = { exam_code: code, exam_date: examDate, weekly_hours: h };
    if (sections.length) body.sections = sections;
    if (startDate) body.start_date = startDate;
    setBusy(true);
    setError(null);
    try {
      onCreated(await api<StudyPlan>("/prep/plans", { method: "POST", body }));
    } catch (err) {
      setError(errText(err));
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit} className={`${CARD} space-y-3`}>
      <div className="flex flex-wrap gap-4">
        <label className="text-sm">
          <span className="mb-1 block text-slate-600">Exam date</span>
          <input
            type="date"
            required
            min={startDate || today}
            value={examDate}
            onChange={(e) => setExamDate(e.target.value)}
            className="rounded border border-slate-300 px-2 py-1"
          />
        </label>
        <label className="text-sm">
          <span className="mb-1 block text-slate-600">Hours per week</span>
          <input
            type="number"
            required
            min={0.5}
            max={112}
            step={0.5}
            value={weeklyHours}
            onChange={(e) => setWeeklyHours(e.target.value)}
            className="w-28 rounded border border-slate-300 px-2 py-1"
          />
        </label>
        <label className="text-sm">
          <span className="mb-1 block text-slate-600">Start date (optional, default today)</span>
          <input
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="rounded border border-slate-300 px-2 py-1"
          />
        </label>
      </div>
      {names.length > 1 && (
        <fieldset className="text-sm">
          <legend className="mb-1 text-slate-600">Papers to cover (none ticked = all)</legend>
          <div className="flex flex-wrap gap-x-4 gap-y-1">
            {names.map((n) => (
              <label key={n} className="flex items-center gap-1">
                <input
                  type="checkbox"
                  checked={sections.includes(n)}
                  onChange={(e) => setSections((cur) => (e.target.checked ? [...cur, n] : cur.filter((x) => x !== n)))}
                />
                {n}
              </label>
            ))}
          </div>
        </fieldset>
      )}
      <p className="text-xs text-slate-500">
        The last 15% of the weeks are for revision and solving downloaded previous year papers; at least 2 whole weeks are needed.
      </p>
      <ErrorNote error={error} />
      <button
        type="submit"
        disabled={busy}
        className="rounded bg-blue-700 px-3 py-1.5 text-sm text-white hover:bg-blue-800 disabled:opacity-50"
      >
        {busy ? "Creating…" : "Create plan"}
      </button>
    </form>
  );
}

const STATUS_STYLE: Record<PlanItemStatus, string> = {
  PENDING: "bg-slate-100 text-slate-700",
  IN_PROGRESS: "bg-amber-100 text-amber-800",
  DONE: "bg-green-100 text-green-800",
  SKIPPED: "bg-slate-200 text-slate-500",
};

const KIND_STYLE: Record<string, string> = {
  TOPIC: "bg-blue-50 text-blue-800",
  REVISION: "bg-purple-50 text-purple-800",
  PYQ: "bg-teal-50 text-teal-800",
};

function PlanView({
  plan,
  syllabus,
  papers,
  onItem,
}: {
  plan: StudyPlan;
  syllabus: Syllabus | null;
  papers: QuestionPaper[] | null;
  onItem: (planId: string, item: PlanItem) => void;
}) {
  const [busy, setBusy] = useState<Record<string, boolean>>({});
  const [error, setError] = useState<string | null>(null);

  // Page links need the very document the plan was generated from; a newer syllabus has other pages.
  const sameExam = syllabus?.exam_code === plan.exam_code;
  const docUrl = sameExam && syllabus?.raw_document_id === plan.syllabus_raw_document_id ? syllabus.notice_url : null;
  const docNote = !sameExam
    ? "Syllabus page links appear once the official syllabus of this exam has loaded."
    : syllabus && syllabus.raw_document_id !== plan.syllabus_raw_document_id
      ? "This plan was built from an earlier version of the syllabus; page numbers refer to that document."
      : null;
  const paperById = useMemo(() => new Map((papers ?? []).map((p) => [p.id, p])), [papers]);

  const weeks = useMemo(() => {
    const m = new Map<number, PlanItem[]>();
    for (const it of [...plan.items].sort((a, b) => a.position - b.position)) {
      const w = m.get(it.planned_week) ?? [];
      w.push(it);
      m.set(it.planned_week, w);
    }
    return Array.from(m.entries()).sort((a, b) => a[0] - b[0]);
  }, [plan.items]);

  const start = parseDay(plan.start_date);
  const currentWeek = Math.floor((Date.now() - start.getTime()) / (7 * 86400000)) + 1;
  const studyWeeks = plan.total_weeks - plan.revision_weeks;
  const total = plan.items.reduce((a, i) => a + i.planned_hours, 0);
  const doneHours = plan.items.filter((i) => i.status === "DONE").reduce((a, i) => a + i.planned_hours, 0);
  const pct = total ? Math.round((doneHours / total) * 100) : 0;

  async function setStatus(item: PlanItem, status: PlanItemStatus) {
    if (item.status === status) return;
    setBusy((b) => ({ ...b, [item.id]: true }));
    setError(null);
    try {
      const updated = await api<PlanItem>(`/prep/plans/${plan.id}/items/${item.id}`, { method: "PATCH", body: { status } });
      onItem(plan.id, updated);
    } catch (e) {
      setError(`${item.topic}: ${errText(e)}${e instanceof ApiError && e.status === 404 ? " (reload the page)" : ""}`);
    } finally {
      setBusy((b) => ({ ...b, [item.id]: false }));
    }
  }

  return (
    <section className="space-y-3">
      <div className={CARD}>
        <h2 className="font-medium">
          <span className="font-mono">{plan.exam_code}</span> plan · exam {fmtDate(plan.target_date)}
        </h2>
        <p className="text-sm text-slate-500">
          {fmtDate(plan.start_date)} to {fmtDate(plan.target_date)} · {plan.total_weeks} weeks ({plan.revision_weeks} revision) ·{" "}
          {hours(plan.weekly_hours)}/week
          {plan.sections?.length ? ` · papers: ${plan.sections.join(", ")}` : " · all papers"} · {plan.generator_version}
        </p>
        <div className="mt-2 flex items-center gap-3 text-sm">
          <div className="h-2 flex-1 rounded bg-slate-100">
            <div className="h-2 rounded bg-green-600" style={{ width: `${pct}%` }} />
          </div>
          <span className="whitespace-nowrap text-slate-600">
            {hours(doneHours)} of {hours(total)} done ({pct}%)
          </span>
        </div>
        {docUrl && (
          <p className="mt-2 text-xs">
            <a className={LINK} href={docUrl} target="_blank" rel="noreferrer">
              Syllabus document this plan cites
            </a>
          </p>
        )}
        {docNote && <p className="mt-2 text-xs text-slate-500">{docNote}</p>}
      </div>
      <ErrorNote error={error} />
      {!weeks.length && <p className="text-sm text-slate-500">This plan has no items.</p>}
      {weeks.map(([week, items]) => {
        const from = addDays(start, (week - 1) * 7);
        const wTotal = items.reduce((a, i) => a + i.planned_hours, 0);
        const wDone = items.filter((i) => i.status === "DONE").length;
        return (
          <div key={week} className={`${CARD} ${week === currentWeek ? "border-blue-400 ring-1 ring-blue-200" : ""}`}>
            <div className="mb-2 flex flex-wrap items-baseline gap-2">
              <h3 className="font-medium">Week {week}</h3>
              <span className="text-sm text-slate-500">
                {shortDay(from)} – {shortDay(addDays(from, 6))}
              </span>
              {week > studyWeeks && <span className="rounded bg-purple-50 px-2 py-0.5 text-xs text-purple-800">revision</span>}
              {week === currentWeek && <span className="rounded bg-blue-100 px-2 py-0.5 text-xs text-blue-800">this week</span>}
              <span className="ml-auto text-sm text-slate-500">
                {wDone}/{items.length} done · {hours(wTotal)}
              </span>
            </div>
            <ul className="divide-y divide-slate-100">
              {items.map((it) => (
                <ItemRow
                  key={it.id}
                  item={it}
                  busy={!!busy[it.id]}
                  docUrl={docUrl}
                  paper={it.question_paper_id ? paperById.get(it.question_paper_id) ?? null : null}
                  papersLoaded={sameExam && papers !== null}
                  onStatus={(s) => setStatus(it, s)}
                />
              ))}
            </ul>
          </div>
        );
      })}
    </section>
  );
}

function ItemRow({
  item,
  busy,
  docUrl,
  paper,
  papersLoaded,
  onStatus,
}: {
  item: PlanItem;
  busy: boolean;
  docUrl: string | null;
  paper: QuestionPaper | null;
  papersLoaded: boolean;
  onStatus: (s: PlanItemStatus) => void;
}) {
  const done = item.status === "DONE";
  return (
    <li className="flex flex-wrap items-center gap-2 py-2 text-sm">
      <input
        type="checkbox"
        aria-label={`Mark "${item.topic}" done`}
        checked={done}
        disabled={busy}
        onChange={(e) => onStatus(e.target.checked ? "DONE" : "PENDING")}
      />
      <span className={`rounded px-1.5 py-0.5 text-xs font-medium ${KIND_STYLE[item.kind] || "bg-slate-100 text-slate-700"}`}>{item.kind}</span>
      <span className={`min-w-0 flex-1 ${done || item.status === "SKIPPED" ? "text-slate-400 line-through" : ""}`}>
        {item.topic}
        {item.section && <span className="block text-xs text-slate-500 no-underline">{item.section}</span>}
      </span>
      <span className="text-xs">
        {item.syllabus_page !== null &&
          (docUrl ? (
            <a className="text-blue-700 underline" href={pageLink(docUrl, item.syllabus_page)} target="_blank" rel="noreferrer">
              syllabus page {item.syllabus_page}
            </a>
          ) : (
            <span className="text-slate-500">syllabus page {item.syllabus_page}</span>
          ))}
        {item.question_paper_id &&
          (paper ? (
            <a className="text-blue-700 underline" href={paper.official_url} target="_blank" rel="noreferrer">
              official paper{paper.size_label ? ` (${paper.size_label})` : ""}
            </a>
          ) : (
            <span className="text-slate-500">{papersLoaded ? "paper no longer listed" : "loading paper link…"}</span>
          ))}
      </span>
      <span className="w-14 text-right text-slate-600">{hours(item.planned_hours)}</span>
      <select
        value={item.status}
        disabled={busy}
        onChange={(e) => onStatus(e.target.value as PlanItemStatus)}
        className={`rounded px-1.5 py-0.5 text-xs ${STATUS_STYLE[item.status] || ""}`}
        aria-label={`Status of "${item.topic}"`}
      >
        {PLAN_ITEM_STATUSES.map((s) => (
          <option key={s} value={s}>
            {s.replace(/_/g, " ")}
          </option>
        ))}
      </select>
      {done && item.completed_at && <span className="w-full pl-6 text-xs text-slate-500">done {fmtDate(item.completed_at, true)}</span>}
    </li>
  );
}
